gn:center}.empty .state-icon{margin:var(--s0) auto var(--s4);background:var(--surface);color:var(--muted)}.empty p{max-width:100%;margin:var(--s3) var(--s0) var(--s6);color:var(--muted)}.offline-header{margin-bottom:var(--s4)}.offline .hero{background:var(--surface);border-color:var(--line)}.offline .rail{background:var(--line)}.offline .elapsed{background:var(--muted)}.sr-only{position:absolute;width:var(--hair);height:var(--hair);padding:var(--s0);overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}.note-display{padding:var(--s3);background:var(--surface);border-radius:var(--r-sm);overflow-wrap:anywhere;margin-bottom:var(--s4)}.caption{font-size:var(--fs-sm);color:var(--muted)}
